}

const totals = {};
for (const row of s.absences) {
  const key = String(row.nom || '').trim();
  if (!key) continue;
  totals[key] = (totals[key] || 0) + 1;
}

const summaryRows = Object.entries(totals)
  .map(([nom, total]) => ({ nom, total }))
  .sort((a, b) => a.nom.localeCompare(b.nom, 'fr'));

const esc = (v) => String(v || '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');

const rowsSummaryHtml = summaryRows.length
  ? summaryRows.map((r) => `<tr><td>${esc(r.nom)}</td><td>${r.total}</td></tr>`).join('')
  : '<tr><td colspan="2">Aucune absence pour le moment</td></tr>';

const rowsDetailsHtml = s.absences.length
  ? s.absences
      .slice()
      .reverse()
      .map((r) => `<tr><td>${esc(r.nom)}</td><td>${esc(r.date_absence)}</td><td>${esc(r.motif)}</td><td>${esc(r.plan_action || '-')}</td><td>${esc(r.statut_action || '-')}</td><td><form method="POST" action="/webhook/absences-ui-v3" style="margin:0"><input type="hidden" name="action" value="delete_one"><input type="hidden" name="id" value="${esc(r.id)}"><button type="submit" class="danger">Supprimer</button></form></td></tr>`)
      .join('')
  : '<tr><td colspan="6">Aucune absence enregistree</td></tr>';

const flash = s.flash && s.flash.text ? s.flash : null;
if (s.flash) delete s.flash;

const flashHtml = flash
  ? `<div class="msg ${flash.isError ? 'err' : 'ok'}">${esc(flash.text)}</div>`
  : '';

const html = `<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>App Absences</title><style>:root{--bg:#f5f7fb;--card:#fff;--txt:#1f2937;--muted:#6b7280;--primary:#2563eb;--ok:#16a34a;--border:#e5e7eb;--danger:#dc2626}*{box-sizing:border-box}body{margin:0;font-family:Inter,Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--txt)}.wrap{max-width:1100px;margin:24px auto;padding:0 16px}.card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:18px;margin-bottom:16px;box-shadow:0 2px 10px rgba(0,0,0,.04)}h1{font-size:26px;margin:0 0 8px}p{margin:0 0 14px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}input,button{width:100%;padding:11px 12px;border-radius:10px;border:1px solid var(--border);font-size:14px}button{cursor:pointer;background:var(--primary);color:#fff;border:none;font-weight:600}.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;background:#111827;color:#fff;border-radius:10px;padding:11px 12px;font-size:14px;font-weight:600}.danger{background:var(--danger)}.msg{margin-top:10px;font-size:14px}.ok{color:var(--ok)}.err{color:#dc2626}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid var(--border);text-align:left;vertical-align:middle}th{background:#f9fafb;font-size:13px}.small{font-size:12px;color:var(--muted)}@media (max-width:720px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="card"><h1>Tableau d'absences</h1><p>Ajoute, consulte et supprime des absences.</p><form method="POST" action="/webhook/absences-ui-v3"><input type="hidden" name="action" value="add"><div class="grid"><input name="nom" placeholder="Nom (ex: Dupont)" required><input name="date_absence" type="date" required><input name="motif" placeholder="Motif (optionnel)"></div><div class="grid" style="margin-top:10px"><select name="plan_action"><option value="">Plan d'action (aucun)</option><option>Avertissement</option><option>Entretien</option><option>Formation</option><option>Suspension</option><option>Autre</option></select><select name="statut_action"><option>A faire</option><option>En cours</option><option>Traite</option></select><div></div></div><div style="margin-top:10px;display:flex;gap:10px"><button type="submit">Ajouter l'absence</button><a class="btn" href="/webhook/absences-ui-v3-report">Tableau pro interactif</a></div></form>${flashHtml}</div><div class="card"><h2 style="margin-top:0">Totaux par nom</h2><table><thead><tr><th>Nom</th><th>Total absences</th></tr></thead><tbody>${rowsSummaryHtml}</tbody></table></div><div class="card"><h2 style="margin-top:0">Liste des absences</h2><table><thead><tr><th>Nom</th><th>Date</th><th>Motif</th><th>Plan d'action</th><th>Statut</th><th>Action</th></tr></thead><tbody>${rowsDetailsHtml}</tbody></table><p class="small">Astuce: utilise \"Supprimer\" sur la ligne concernee.</p></div></div></body></html>`;

return [{ json: { html } }];

const input = $json || {};
const body = input.body || {};
const action = String(body.action || '').toLowerCase();

const s = $getWorkflowStaticData('global');
if (!Array.isArray(s.absences)) s.absences = [];
for (const row of s.absences) {
  if (!row.id) row.id = row.cree_le || `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

let flash = '';
let isError = false;

if (action === 'add') {
  const nom = String(body.nom || '').trim();
  const date_absence = String(body.date_absence || '').trim();
  const motif = String(body.motif || '').trim();
  const plan_action = String(body.plan_action || '').trim();
  const statut_action = String(body.statut_action || 'A faire').trim();

  if (!nom || !date_absence) {
    flash = 'Merci de remplir le nom et la date.';
    isError = true;
  } else {
    const id = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    s.absences.push({ id, nom, date_absence, motif, plan_action, statut_action, cree_le: new Date().toISOString() });
    const totalNom = s.absences.filter((r) => r.nom === nom).length;
    flash = `Absence ajoutee pour ${nom}. Total pour ce nom: ${totalNom}`;
  }
}

if (action === 'delete_one') {
  const id = String(body.id || '').trim();
  const before = s.absences.length;
  s.absences = s.absences.filter((r) => String(r.id || '') !== id);
  if (s.absences.length < before) {
    flash = 'Absence supprimee.';
  } else {
    flash = 'Absence introuvable.';
    isError = true;
  }
}

if (action === 'delete_by_name') {
  const nom = String(body.nom || '').trim();
  if (!nom) {
    flash = 'Merci de saisir un nom a supprimer.';
    isError = true;
  } else {
    const before = s.absences.length;
    s.absences = s.absences.filter((r) => String(r.nom || '').trim() !== nom);
    const deleted = before - s.absences.length;
    if (deleted > 0) {
      flash = `${deleted} absence(s) supprimee(s) pour ${nom}.`;
    } else {
      flash = `Aucune absence trouvee pour ${nom}.`;
      isError = true;
    }
  }
}

if (action === 'cleanup_tests') {
  const before = s.absences.length;
  s.absences = s.absences.filter((r) => !['Test User', 'PRENOM'].includes(String(r.nom || '').trim()));
  const deleted = before - s.absences.length;
  flash = `${deleted} ligne(s) de test supprimee(s).`;
}

s.flash = { text: flash, isError };
return [{ json: { ok: true } }];

const s = $getWorkflowStaticData('global');
const rows = Array.isArray(s.absences) ? s.absences.slice() : [];

const esc = (v) => String(v ?? '')
  .replaceAll('&', '&amp;')
  .replaceAll('<', '&lt;')
  .replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;');

const byName = {};
for (const r of rows) {
  const nom = String(r.nom || '').trim() || 'Sans nom';
  byName[nom] = (byName[nom] || 0) + 1;
}

const summaryRows = Object.entries(byName)
  .map(([nom, total]) => ({ nom, total }))
  .sort((a, b) => a.nom.localeCompare(b.nom, 'fr'));

const totalAbsences = rows.length;
const totalPersonnes = summaryRows.length;
const exportDate = new Date().toLocaleString('fr-FR');

const detailsHtml = rows.length
  ? rows
      .slice()
      .reverse()
      .map((r, idx) => `<tr><td class="c">${idx + 1}</td><td>${esc(r.nom)}</td><td class="c">${esc(r.date_absence)}</td><td>${esc(r.motif)}</td><td class="c">${esc(r.cree_le)}</td></tr>`)
      .join('')
  : '<tr><td colspan="5" class="empty">Aucune absence</td></tr>';

const summaryHtml = summaryRows.length
  ? summaryRows.map((r) => `<tr><td>${esc(r.nom)}</td><td class="c strong">${r.total}</td></tr>`).join('')
  : '<tr><td colspan="2" class="empty">Aucune donnee</td></tr>';

const html = `<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Export Absences</title>
<style>
  body { font-family: Segoe UI, Arial, sans-serif; background:#f4f7fb; margin:24px; color:#10233c; }
  .wrap { max-width: 1280px; margin:0 auto; }
  .title { font-size:28px; font-weight:800; margin:0 0 6px; }
