  .cards { display:grid; grid-template-columns: repeat(3, 1fr); gap:14px; margin-bottom:20px; }
  .card { background:#fff; border:1px solid #dfe7f3; border-radius:12px; padding:14px 16px; }
  .card .k { font-size:13px; color:#5d6f88; }
  .card .v { font-size:28px; font-weight:800; color:#0b4f8a; margin-top:6px; }
  h2 { margin:20px 0 10px; font-size:20px; }
  table { width:100%; border-collapse:separate; border-spacing:0; background:#fff; border:1px solid #dfe7f3; border-radius:12px; overflow:hidden; }
  th { background:linear-gradient(180deg,#0f62a8,#0b4f8a); color:#fff; text-align:left; padding:12px 14px; font-size:14px; }
  td { padding:12px 14px; border-top:1px solid #eef3fa; font-size:14px; }
  tr:nth-child(even) td { background:#f9fcff; }
  .c { text-align:center; }
  .strong { font-weight:700; }
  .empty { text-align:center; color:#6c7f98; padding:20px; }
</style>
</head>
<body>
  <div class="wrap">
    <h1 class="title">Tableau des absences - Export visuel</h1>
    <p class="sub">Export du ${esc(exportDate)} (donnees synchronisees avec l'app)</p>

    <div class="cards">
      <div class="card"><div class="k">Total absences</div><div class="v">${totalAbsences}</div></div>
      <div class="card"><div class="k">Personnes concernees</div><div class="v">${totalPersonnes}</div></div>
      <div class="card"><div class="k">Dernier export</div><div class="v" style="font-size:18px">${esc(exportDate)}</div></div>
    </div>

    <h2>Resume par nom</h2>
    <table>
      <thead><tr><th>Nom</th><th class="c">Total absences</th></tr></thead>
      <tbody>${summaryHtml}</tbody>
    </table>

    <h2>Details des absences</h2>
    <table>
      <thead><tr><th class="c">#</th><th>Nom</th><th class="c">Date absence</th><th>Motif</th><th class="c">Cree le</th></tr></thead>
      <tbody>${detailsHtml}</tbody>
    </table>
  </div>
</body>
</html>`;

return [{ json: { html } }];

const s = $getWorkflowStaticData('global');
const rows = Array.isArray(s.absences) ? s.absences.slice() : [];

const safeRows = rows.map((r, i) => ({
  idx: i + 1,
  nom: String(r.nom || ''),
  date_absence: String(r.date_absence || ''),
  motif: String(r.motif || ''),
  plan_action: String(r.plan_action || ''),
  statut_action: String(r.statut_action || ''),
  cree_le: String(r.cree_le || ''),
}));

const jsonRows = JSON.stringify(safeRows)
  .replaceAll('<', '\\u003c')
  .replaceAll('>', '\\u003e')
  .replaceAll('&', '\\u0026');

const html = `<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Rapport interactif absences</title>
<style>
  :root { --bg:#f2f6fb; --card:#fff; --line:#dbe5f1; --text:#1a2b44; --muted:#60738f; --primary:#0b5cab; }
  *{box-sizing:border-box}
  body{margin:0;background:var(--bg);font-family:Segoe UI,Arial,sans-serif;color:var(--text)}
  .wrap{max-width:1320px;margin:24px auto;padding:0 16px}
  .card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px;margin-bottom:14px;box-shadow:0 3px 12px rgba(0,0,0,.05)}
  h1{margin:0 0 6px;font-size:30px}
  .sub{color:var(--muted);margin:0}
  .filters{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr 1fr auto;gap:10px;align-items:end}
  label{font-size:12px;color:var(--muted);display:block;margin-bottom:4px}
  input,select,button{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:10px;font-size:14px}
  button{cursor:pointer;background:var(--primary);border:none;color:#fff;font-weight:700}
  .btn-secondary{background:#334155}
  .stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
  .stat{background:#f8fbff;border:1px solid var(--line);border-radius:10px;padding:10px}
  .k{font-size:12px;color:var(--muted)} .v{font-size:24px;font-weight:800}
  table{width:100%;border-collapse:separate;border-spacing:0;border:1px solid var(--line);border-radius:12px;overflow:hidden}
  th{background:linear-gradient(180deg,#0b67bb,#0b5cab);color:#fff;padding:12px;text-align:left;font-size:13px;cursor:pointer;user-select:none;white-space:nowrap}
  td{padding:11px;border-top:1px solid #edf2f8;background:#fff;font-size:14px}
  tr:nth-child(even) td{background:#f9fcff}
  .c{text-align:center}
  .empty{padding:18px;text-align:center;color:var(--muted)}
  .hint{font-size:12px;color:var(--muted);margin-top:8px}
  @media (max-width:1100px){.filters{grid-template-columns:1fr 1fr}.stats{grid-template-columns:1fr 1fr}}
</style>
</head>
<body>
<div class="wrap">
  <div class="card">
    <h1>Rapport interactif des absences</h1>
    <p class="sub">Tri, filtre et recherche en direct (ordre alphabetique, date, creation/horaire)</p>
  </div>

  <div class="card">
    <div class="filters">
      <div><label>Recherche</label><input id="q" placeholder="Nom, motif, plan d'action..."></div>
      <div><label>Periode</label><select id="period"><option value="global">Global</option><option value="week_current">Semaine en cours</option><option value="week_prev">Semaine precedente</option><option value="month_current">Mois en cours</option></select></div>
      <div><label>Nom</label><select id="nomFilter"><option value="">Tous</option></select></div>
      <div><label>Plan d'action</label><select id="planFilter"><option value="">Tous</option><option>Avertissement</option><option>Entretien</option><option>Formation</option><option>Suspension</option><option>Autre</option></select></div>
      <div><label>Date du</label><input id="dateFrom" type="date"></div>
      <div><label>Date au</label><input id="dateTo" type="date"></div>
      <div><label>Trier par</label><select id="sortBy"><option value="nom_asc">Nom A→Z</option><option value="nom_desc">Nom Z→A</option><option value="date_asc">Date ancienne→recente</option><option value="date_desc">Date recente→ancienne</option><option value="created_desc">Creation recente→ancienne</option><option value="created_asc">Creation ancienne→recente</option></select></div>
      <div><button id="resetBtn" class="btn-secondary">Reinitialiser</button></div>
    </div>
    <p class="hint">Astuce: clique sur les titres de colonnes pour trier rapidement.</p>
  </div>

  <div class="card">
    <div class="stats">
      <div class="stat"><div class="k">Absences affichees</div><div class="v" id="s1">0</div></div>
      <div class="stat"><div class="k">Total absences (global)</div><div class="v" id="s2">0</div></div>
      <div class="stat"><div class="k">Personnes distinctes</div><div class="v" id="s3">0</div></div>
      <div class="stat"><div class="k">Derniere mise a jour</div><div class="v" id="s4" style="font-size:16px"></div></div>
    </div>
  </div>

  <div class="card">
    <table>
      <thead>
        <tr>
          <th class="c" data-key="idx">#</th>
          <th data-key="nom">Nom</th>
          <th class="c" data-key="date_absence">Date absence</th>
          <th data-key="motif">Motif</th>
          <th data-key="plan_action">Plan d'action</th>
          <th data-key="statut_action">Statut</th>
          <th class="c" data-key="cree_le">Cree le (horaire)</th>
        </tr>
      </thead>
      <tbody id="tbody"></tbody>
    </table>
  </div>
</div>

<script>
const ALL = ${jsonRows};
let clickableSort = null;

function fmtDate(v){ if(!v) return ''; const d = new Date(v); return isNaN(d) ? v : d.toLocaleDateString('fr-FR'); }
function fmtDateTime(v){ if(!v) return ''; const d = new Date(v); return isNaN(d) ? v : d.toLocaleString('fr-FR'); }
function normalize(v){ return String(v||'').toLowerCase().trim(); }
function toNumDate(v){ const d = new Date(v); return isNaN(d) ? 0 : d.getTime(); }
function esc(v){ return String(v||'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;'); }

function getPeriodRange(period){
  const now = new Date();
  const y = now.getFullYear();
  const m = now.getMonth();
  const day = now.getDay();
  const mondayOffset = day === 0 ? -6 : 1 - day;
  const weekStart = new Date(now);
  weekStart.setHours(0,0,0,0);
  weekStart.setDate(now.getDate() + mondayOffset);

  if (period === 'week_current') {
    const start = new Date(weekStart);
    const end = new Date(weekStart); end.setDate(end.getDate() + 6);
    return { start, end };
  }
  if (period === 'week_prev') {
    const start = new Date(weekStart); start.setDate(start.getDate() - 7);
    const end = new Date(weekStart); end.setDate(end.getDate() - 1);
    return { start, end };
  }
  if (period === 'month_current') {
    const start = new Date(y, m, 1);
    const end = new Date(y, m + 1, 0);
    return { start, end };
  }
  return null;
}

function inRange(dateStr, range){
  if (!range) return true;
  if (!dateStr) return false;
  const d = new Date(dateStr + 'T00:00:00');
  if (isNaN(d)) return false;
  const start = new Date(range.start); start.setHours(0,0,0,0);
  const end = new Date(range.end); end.setHours(23,59,59,999);
  return d >= start && d <= end;
}

function apply(){
  const q = normalize(document.getElementById('q').value);
  const period = document.getElementById('period').value;
  const nomFilter = document.getElementById('nomFilter').value;
  const df = document.getElementById('dateFrom').value;
  const dt = document.getElementById('dateTo').value;
  const sortBy = clickableSort || document.getElementById('sortBy').value;

  const periodRange = getPeriodRange(period);

  let rows = ALL.filter(r => {
    const txt = normalize(r.nom + ' ' + r.motif + ' ' + r.plan_action + ' ' + r.statut_action + ' ' + r.date_absence + ' ' + r.cree_le);
    if (q && !txt.includes(q)) return false;
    if (nomFilter && r.nom !== nomFilter) return false;
    const planFilter = document.getElementById('planFilter').value;
    if (planFilter && r.plan_action !== planFilter) return false;
    if (!inRange(r.date_absence, periodRange)) return false;
    if (df && String(r.date_absence || '') < df) return false;
    if (dt && String(r.date_absence || '') > dt) return false;
    return true;
  });

  rows.sort((a,b)=>{
    switch(sortBy){
      case 'nom_desc': return b.nom.localeCompare(a.nom,'fr');
      case 'date_asc': return String(a.date_absence).localeCompare(String(b.date_absence));
      case 'date_desc': return String(b.date_absence).localeCompare(String(a.date_absence));
      case 'created_asc': return toNumDate(a.cree_le)-toNumDate(b.cree_le);
      case 'created_desc': return toNumDate(b.cree_le)-toNumDate(a.cree_le);
      case 'idx': return a.idx-b.idx;
      case 'nom': return a.nom.localeCompare(b.nom,'fr');
      case 'date_absence': return String(a.date_absence).localeCompare(String(b.date_absence));
      case 'motif': return String(a.motif).localeCompare(String(b.motif),'fr');
      case 'plan_action': return String(a.plan_action).localeCompare(String(b.plan_action),'fr');
      case 'statut_action': return String(a.statut_action).localeCompare(String(b.statut_action),'fr');
      case 'cree_le': return toNumDate(a.cree_le)-toNumDate(b.cree_le);
      default: return a.nom.localeCompare(b.nom,'fr');
    }
  });

  const tbody = document.getElementById('tbody');
  if (!rows.length){
    tbody.innerHTML = '<tr><td colspan="7" class="empty">Aucune ligne correspondante</td></tr>';
  } else {
    tbody.innerHTML = rows.map(function(r){ return '<tr><td class="c">'+r.idx+'</td><td>'+esc(r.nom)+'</td><td class="c">'+esc(fmtDate(r.date_absence))+'</td><td>'+esc(r.motif)+'</td><td>'+esc(r.plan_action || '-')+'</td><td>'+esc(r.statut_action || '-')+'</td><td class="c">'+esc(fmtDateTime(r.cree_le))+'</td></tr>'; }).join('');
  }

  document.getElementById('s1').textContent = rows.length;
  document.getElementById('s2').textContent = ALL.length;
  document.getElementById('s3').textContent = new Set(rows.map(r=>r.nom).filter(Boolean)).size;
  document.getElementById('s4').textContent = new Date().toLocaleString('fr-FR');
}

function init(){
  const names = [...new Set(ALL.map(r=>r.nom).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr'));
  const sel = document.getElementById('nomFilter');
  sel.innerHTML = '<option value="">Tous</option>' + names.map(function(n){ return '<option value="'+n.replaceAll('"','&quot;')+'">'+esc(n)+'</option>'; }).join('');

  ['q','period','nomFilter','planFilter','dateFrom','dateTo','sortBy'].forEach(id => {
    document.getElementById(id).addEventListener('input', function(){ clickableSort = null; apply(); });
  });

  document.getElementById('resetBtn').addEventListener('click', function(){
    document.getElementById('q').value='';
    document.getElementById('period').value='global';
    document.getElementById('nomFilter').value='';
    document.getElementById('planFilter').value='';
    document.getElementById('dateFrom').value='';
    document.getElementById('dateTo').value='';
    document.getElementById('sortBy').value='nom_asc';
    clickableSort = null;
    apply();
  });

  document.querySelectorAll('th[data-key]').forEach(function(th){
    th.addEventListener('click', function(){
      clickableSort = th.getAttribute('data-key');
